package com.findback.app;

import android.Manifest;import android.app.Activity;import android.app.AlertDialog;import android.content.ComponentName;import android.content.Intent;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.Build;import android.os.Bundle;import android.provider.Settings;import android.provider.Settings.Secure;import android.text.InputFilter;import android.text.InputType;import android.view.View;import android.widget.*;import android.view.ViewGroup;

/** Setup screen. Recovery mode cannot be armed until all required access is ready. */
public class MainActivity extends Activity {
    private static final int REQUEST_LOCATION=7; private static final int INK=Color.rgb(23,61,52), MUTED=Color.rgb(83,110,100), TEAL=Color.rgb(7,133,109), BG=Color.rgb(243,247,242);
    private EditText code; private TextView checklist; private Switch mode; private boolean updating;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);setContentView(screen());refresh();}
    @Override protected void onResume(){super.onResume();refresh();}
    private View screen(){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(BG);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(20),dp(28),dp(20),dp(30));scroll.addView(page);
        TextView title=txt("FindBack",31,INK,true);page.addView(title);page.addView(txt("Secure lost-phone recovery",16,MUTED,false));
        LinearLayout intro=card(page);add(intro,"HOW IT WORKS",13,TEAL,true,0,0,0,8);add(intro,"Set up this Android phone before it is lost. From another phone, send FIND plus your private 8-digit code to its WhatsApp number. If this phone is online and permissions are ready, FindBack attempts to reply with its location and status.",15,INK,false,0,0,0,0);
        LinearLayout codeCard=card(page);add(codeCard,"1  •  Save a private recovery code",19,INK,true,0,0,0,5);add(codeCard,"Choose exactly 8 digits and keep them private.",14,MUTED,false,0,0,0,10);code=new EditText(this);code.setSingleLine(true);code.setHint("8-digit code");code.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);code.setFilters(new InputFilter[]{new InputFilter.LengthFilter(8)});code.setPadding(dp(14),dp(10),dp(14),dp(10));code.setBackground(bg(Color.WHITE,Color.rgb(210,225,216)));codeCard.addView(code,new LinearLayout.LayoutParams(-1,dp(52)));Button save=button("Save code",true);codeCard.addView(save,buttonLayout());save.setOnClickListener(v->save());
        LinearLayout perm=card(page);add(perm,"2  •  Grant Android permissions",19,INK,true,0,0,0,4);add(perm,"FindBack needs location permission to prepare a reply. Notification access lets Android show FindBack incoming WhatsApp notification text and its reply action. Android notification access is broad; FindBack filters to WhatsApp and does not save message text.",14,MUTED,false,0,0,0,8);Button loc=button("Set up location access",false);perm.addView(loc,buttonLayout());loc.setOnClickListener(v->location());Button not=button("Allow WhatsApp command access",false);perm.addView(not,buttonLayout());not.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));
        LinearLayout active=card(page);add(active,"3  •  Recovery mode",19,INK,true,0,0,0,2);mode=new Switch(this);mode.setText("Enable FindBack on this phone");mode.setTextColor(INK);active.addView(mode);mode.setOnCheckedChangeListener((v,on)->{if(updating)return;if(on){String missing=missingSetup();if(!missing.isEmpty()){new AlertDialog.Builder(this).setTitle("Finish setup first").setMessage(missing).setPositiveButton("OK",null).show();updating=true;mode.setChecked(false);updating=false;return;}}RecoveryStore.setArmed(this,on);refresh();});CheckBox beep=new CheckBox(this);beep.setText("Play an alert for a valid request");beep.setTextColor(INK);beep.setChecked(RecoveryStore.beep(this));active.addView(beep);beep.setOnCheckedChangeListener((v,on)->RecoveryStore.setBeep(this,on));add(active,"A normal app cannot guarantee sound through Silent or Do Not Disturb.",13,MUTED,false,0,0,0,0);
        LinearLayout status=card(page);add(status,"SETUP READINESS",13,TEAL,true,0,0,0,8);checklist=txt("Checking…",14,INK,false);status.addView(checklist);
        LinearLayout limit=card(page);limit.setBackground(bg(Color.rgb(255,245,229),Color.rgb(235,216,185)));add(limit,"Important limits",16,Color.rgb(123,75,27),true,0,0,0,5);add(limit,"The target phone must be on, connected to the internet, and receiving WhatsApp notifications. A cached location can be old. If the phone is offline or switched off, it cannot send a WhatsApp reply. This version does not automatically save a location before shutdown.",14,Color.rgb(99,78,49),false,0,0,0,0);
        TextView sample=txt("Example command:  FIND <your 8-digit code>",14,MUTED,true);sample.setGravity(17);page.addView(sample);return scroll;}
    private void save(){String value=code.getText().toString().trim();if(!RecoveryStore.validCode(value)){code.setError("Enter exactly 8 digits");return;}RecoveryStore.saveCode(this,value);code.setText("");code.setHint("Code saved on this phone");Toast.makeText(this,"Code saved. Keep it private.",Toast.LENGTH_LONG).show();refresh();}
    private void location(){if(!hasLocation()){if(Build.VERSION.SDK_INT>=23)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},REQUEST_LOCATION);return;}new AlertDialog.Builder(this).setTitle("Allow location in the background").setMessage("To answer a request when FindBack is closed, Android needs background location access. Open app permissions and choose Allow all the time. Keep Android Location switched on.").setNegativeButton("Later",null).setPositiveButton("Open settings",(d,w)->openSettings()).show();}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQUEST_LOCATION){if(hasLocation())location();else Toast.makeText(this,"Location access is required.",Toast.LENGTH_LONG).show();refresh();}}
    private void openSettings(){startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.fromParts("package",getPackageName(),null)));}
    private boolean hasLocation(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private boolean hasBackground(){return Build.VERSION.SDK_INT<29||checkSelfPermission(Manifest.permission.ACCESS_BACKGROUND_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private boolean hasListener(){String v=Secure.getString(getContentResolver(),"enabled_notification_listeners");return v!=null&&v.contains(new ComponentName(this,WhatsAppCommandListener.class).flattenToString());}
    private String missingSetup(){StringBuilder b=new StringBuilder();if(!RecoveryStore.configured(this))b.append("• Save the 8-digit code\n");if(!hasLocation())b.append("• Grant location permission\n");else if(!hasBackground())b.append("• Set location to Allow all the time in Android settings\n");if(!hasListener())b.append("• Enable FindBack in Notification access settings\n");return b.toString();}
    private void refresh(){if(checklist==null)return;String l=hasLocation()?(hasBackground()?"✓ Location access ready":"! Choose ‘Allow all the time’ for location"):"○ Location permission needed";String n=hasListener()?"✓ WhatsApp notification access ready":"○ Notification access needed";String c=RecoveryStore.configured(this)?"✓ Private code saved":"○ Save a recovery code";checklist.setText(c+"\n"+l+"\n"+n+"\n"+(RecoveryStore.armed(this)?"✓ Recovery mode ON":"○ Recovery mode OFF"));if(mode!=null){updating=true;mode.setChecked(RecoveryStore.armed(this));updating=false;}}
    private LinearLayout card(LinearLayout page){LinearLayout a=new LinearLayout(this);a.setOrientation(1);a.setPadding(dp(16),dp(15),dp(16),dp(15));a.setBackground(bg(Color.WHITE,Color.rgb(222,233,225)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(14);page.addView(a,p);return a;}
    private void add(LinearLayout p,String s,int z,int color,boolean bold,int l,int t,int r,int b){TextView v=txt(s,z,color,bold);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,-2);q.setMargins(dp(l),dp(t),dp(r),dp(b));p.addView(v,q);}
    private TextView txt(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
    private Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:TEAL);b.setBackground(bg(primary?TEAL:Color.rgb(229,242,234),primary?TEAL:Color.rgb(229,242,234)));return b;}
    private LinearLayout.LayoutParams buttonLayout(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.topMargin=dp(7);return p;}
    private android.graphics.drawable.GradientDrawable bg(int fill,int stroke){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(14));d.setStroke(dp(1),stroke);return d;}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
}
